      body: "한국사 1·2등급의 비밀은 오답노트 정착이에요. 단순 풀이만 하면 같은 실수 반복됩니다. 핵심은 \"오답 4유형 분류 + 사료·흐름 정리법 + 1·1·3 재풀이 사이클 + 시험 D-7 활용\" 4박자예요. 한국사 오답은 4유형 (시대 혼동·인물·사건 혼동·사료 오독·흐름 부족)으로 분류해서 영역별 약점을 진단할 수 있어요. 단순 정답·오답 기록이 아니라 \"왜 이 풀이? 사료는 어느 시대? 인물·사건 연결은?\" 메타 정리가 1·2등급의 비밀입니다. 1:1 과외에서 오답노트 첨삭이 가장 효율적이에요."
