      body: "고조선은 한국사 시험에서 매년 1~2문항 고정 출제되는 핵심 영역이에요. 단순 \"단군 신화\" 암기로는 1·2등급 못 가요. \"단군조선 → 기자조선 (학설) → 위만조선 → 한사군\" 4단계 흐름이 핵심이고, 특히 8조법·위만조선·한사군은 사료 분석으로 자주 출제됩니다. \"단군 신화의 의미·8조법의 사회상·위만조선의 발전·한사군 설치\" 4가지 핵심 포인트를 인과관계로 정리하는 게 답이에요. 1:1 과외에서 고조선은 1~2시간이면 정복 가능합니다."
