      {title: "위만이 외래라서 위만조선은 중국 역사?", body: "절대 아니에요. 위만은 연나라 출신이지만 \"조선\"이라는 국호를 유지하고, 고조선 사회 구조를 계승했어요. 따라서 위만조선은 우리 역사입니다. 시험에서 \"위만조선의 정체성\"은 자주 출제되는 사고형 문항이에요."}
