    checklist: ["단군 신화 사회적 의미 3가지?","8조법 3조항 사회상 분석 가능?","단군조선·위만조선 시기 구분?","위만조선의 발전 (철기·중계 무역) 이해?","한사군 4개·멸망 시기 외웠나요?"],
    checklistTitle: "고조선 정복 체크리스트",
    checklistSub: "중·고등 학년별 점검",
    faqs: [
      {q: "단군 신화는 사실인가요?", a: "단군 신화는 신화 자체가 사실이라기보다 \"고조선 건국의 역사적 배경을 신화로 표현한 것\"이에요. 단군이 실존 인물인지는 학계에서 논란이 있지만, 고조선이 BC 2333년경 건국되어 청동기·철기 시대에 걸쳐 존재한 우리나라 최초의 국가라는 사실은 분명합니다. 시험에서는 신화의 \"사회적 의미\" (농경·제정일치·홍익인간)를 묻는 문항이 자주 출제돼요."},
      {q: "기자조선은 실제로 있었나요?", a: "기자조선은 \"중국 기자가 동래해 조선을 세웠다\"는 설인데, 현재 학계에서는 부정적으로 봅니다. 중국 측 사료에만 등장하고 한국 측 고고학 증거가 없어요. 시험에서는 \"기자조선설은 사대주의적 관점\"이라는 비판적 관점이 출제됩니다. 단군조선 → 위만조선 흐름이 정설이에요."},
      {q: "8조법은 어떻게 외워야 하나요?", a: "사료 본문 자체를 외우는 게 답이에요. \"사람을 죽인 자는 사형, 남을 다치게 한 자는 곡식으로 배상, 도둑질한 자는 노비\" 3조항을 외우고, 각 조항이 무엇을 의미하는지 (생명 존중·농경/사유 재산·계급 사회) 함께 정리. 1:1 과외에서 사료 분석 시연이 가장 효율적입니다."},
      {q: "한사군은 우리 역사인가요, 중국 역사인가요?", a: "한사군은 한나라가 한반도에 설치한 식민 통치 기구로, 중국 측 행정 구역이에요. 따라서 한사군 자체는 우리 역사가 아니지만, 한사군 시기 우리나라 토착 사회 (삼한·고구려)의 저항과 성장은 우리 역사입니다. 시험에서는 \"한사군의 영향과 한계\"가 자주 출제돼요."}
    ],
