      body: "삼국 시대는 한국사 시험에서 매년 3~5문항 출제되는 최대 비중 영역이에요. 고구려·백제·신라 3국의 건국 → 발전 → 전성기 → 통일 전쟁 흐름이 핵심이고, 특히 \"각국의 전성기 왕\"은 거의 매년 출제됩니다. 광개토대왕·근초고왕·진흥왕은 절대 헷갈리면 안 돼요. \"건국 신화 → 율령 반포 → 불교 수용 → 전성기 영토 확장 → 통일 전쟁\" 5단계 흐름을 3국 비교표로 정리하는 게 1·2등급의 비밀이에요. 1:1 과외에서 삼국 시대는 5~8시간이면 정복 가능합니다."
