    checklist: ["통일신라 신문왕 5대 개혁 외웠나요?","9주 5소경 vs 5경 15부 62주 구분?","발해의 고구려 계승 의식 3가지 근거?","통일신라 문화재 (석굴암·불국사·무구정광대다라니경) 의미?","호족 등장 → 후삼국 → 고려 흐름 이해?"],
    checklistTitle: "남북국 시대 정복 체크리스트",
    checklistSub: "중·고등 학년별 점검",
    faqs: [
      {q: "왜 \"남북국 시대\"라고 부르나요?", a: "조선 후기 실학자 유득공이 \"발해고\"에서 처음 사용한 용어예요. 통일신라 (남) + 발해 (북) 두 나라가 우리 민족의 두 줄기로 동시에 존재했음을 강조하는 표현입니다. 일제강점기까지 발해는 우리 역사에서 소외되었지만, 광복 후 본격적으로 우리 역사로 자리매김했어요. 중국의 동북공정에 맞서 발해 = 우리 역사 인식을 강화하는 게 중요합니다."},
      {q: "통일신라의 \"녹읍\"과 \"관료전\"은 무엇인가요?", a: "녹읍 = 귀족이 토지에서 조세·노동력 모두 거두는 권리 (귀족 권력 ↑). 관료전 = 토지에서 조세만 거두는 권리 (왕권 ↑·귀족 권력 ↓). 신문왕이 녹읍 폐지·관료전 지급으로 왕권을 강화했지만, 8세기 경덕왕 때 녹읍 부활로 다시 귀족 권력이 커져요. 시험에서 \"녹읍 폐지·부활 시기\"가 자주 출제됩니다."},
      {q: "발해의 \"해동성국\"은 무슨 의미인가요?", a: "\"해동성국 (海東盛國)\" = 동쪽 바다의 성대한 나라. 9세기 발해 선왕 (818~830) 시기 중국 당나라가 발해를 부른 별명이에요. 발해 전성기를 의미합니다. 5경 15부 62주 행정 구역 정비, 영토 최대 (만주·연해주·한반도 북부), 당과 대등한 외교가 \"해동성국\"의 근거예요. 시험에서 \"해동성국 = 선왕 = 9세기 전성기\" 매칭이 단골입니다."},
      {q: "통일신라가 멸망한 진짜 이유는?", a: "복합적이에요. ① 골품제 모순 (6두품 불만), ② 진골 귀족의 왕위 다툼, ③ 녹읍 부활로 귀족 경제력 비대화, ④ 농민 반란 (원종·애노의 난), ⑤ 호족 등장. 결국 \"중앙 권력 약화 + 지방 호족 성장 + 농민 불만\"이 동시에 작동해 후삼국 분열로 이어진 거예요. 시험에서는 \"멸망 원인 4~5가지\" 묻는 서술형 문항이 자주 출제됩니다."}
    ],
