    areas: [
      {name: "건국·기반 (918~10세기·왕건·광종·성종)", body: "고려는 918년 왕건 (태조)이 후고구려 궁예를 몰아내고 건국, 936년 후백제 견훤·신라 항복을 받으며 후삼국을 통일한 나라예요. 왕건의 정책: ① 호족 통합 (혼인 정책·사성 정책·기인 제도), ② 북진 정책 (서경 중시·발해 유민 포용), ③ 훈요 10조 (불교·풍수·민본). 광종 (949~975)의 개혁이 핵심이에요: 노비안검법 (956)·과거제 (958·쌍기 제안)·관복 제정·연호 \"광덕·준풍\". 성종 (981~997)은 최승로의 시무 28조를 받아 유교 정치 (12목·향리·학교)를 정착시켰어요. \"왕건 통합·광종 왕권·성종 유교\" 3단계가 고려 기반이에요."},
      {name: "무신 정변·항몽 (12~13세기)", body: "고려 중기는 무신 정변과 몽골 항쟁의 격동기예요. 무신 정변 (1170, 정중부·이의방·이고)은 의종의 향락 정치와 문신 우위에 대한 반발로 일어났어요. 이후 무신들의 권력 투쟁 (이의방→정중부→경대승→이의민)이 이어지고, 최충헌 (1196)이 정권 장악 후 최씨 정권 (1196~1258, 4대 60여 년)이 안정. 몽골 침입 (1231~1259, 6차)에 대해 최우는 강화 천도 (1232)로 항쟁했어요. 1259년 몽골과 강화 후 개경 환도 (1270), 삼별초 (배중손·김통정)는 진도·제주에서 1273년까지 항쟁. 팔만대장경 조판 (1236~1251)도 이 시기예요. 무신 정변 시기·인물·강화 천도·삼별초가 단골 출제."},
      {name: "원 간섭·공민왕 개혁 (14세기)", body: "원 간섭기 (1270~1356)는 고려가 원나라의 부마국이 되어 자주성을 잃은 시기예요. 부원 세력 (기철·권문세족) 득세, 영토 축소 (쌍성총관부·동녕부·탐라총관부), 정동행성 설치, 일본 원정 (강제 동원). 공민왕 (1351~1374)이 반원 자주 개혁을 단행: ① 친원파 숙청 (기철 제거), ② 쌍성총관부 회복 (1356·철령 이북 수복), ③ 정동행성 폐지, ④ 신돈 등용·전민변정도감 (권문세족 노비·토지 환수), ⑤ 신진사대부 등용 (이색·정몽주·정도전). 그러나 신돈 실각·홍건적·왜구 침입으로 개혁이 좌절되고, 1392년 이성계의 위화도 회군 → 신진사대부와 결합 → 조선 건국으로 이어집니다."},
      {name: "고려 문화 (불교·청자·인쇄·역사서)", body: "고려는 한국 문화의 황금기 중 하나예요. ① 불교: 의천 (천태종·교관겸수)·지눌 (조계종·정혜쌍수·돈오점수). ② 인쇄: 초조대장경 (현종)·팔만대장경 (재조대장경, 최우, 1236~1251, 해인사 보관, 유네스코)·금속활자 (직지심체요절 1377, 청주 흥덕사, 세계 최고 금속활자, 유네스코). ③ 청자: 12세기 비색 청자·상감 기법 (\"청자 상감 운학문 매병\"). ④ 역사서: \"삼국사기\" (김부식, 1145, 기전체, 신라 중심 사대주의)·\"삼국유사\" (일연, 1281, 단군 신화 최초 수록·민족 의식)·\"제왕운기\" (이승휴, 1287). 시험에서는 팔만대장경·직지·삼국사기·삼국유사가 거의 매년 출제돼요."}
    ],
    tiers: [
      {label: "초등·중1 (입문)", body: "왕건·광종·무신 정변·몽골 항쟁·공민왕·이성계 6대 키워드만 정리. 한국사 만화·드라마 (\"태조 왕건\"·\"무인시대\")로 시각 학습. 1:1 과외 추천."},
      {label: "중2·3 (개념 정리)", body: "고려 4단계 흐름 + 광종·성종 개혁 + 무신 정변·강화 천도 + 공민왕 개혁 + 고려 문화 (팔만대장경·직지·삼국사기·삼국유사) 정리. 1:1 과외에서 표 정리 효율적."},
      {label: "고1·2 (수능·한능검)", body: "출제 비중 15~20%. 광종 정책 (노비안검·과거제)·무신 정권·몽골 6차 침입·삼별초·공민왕 개혁 5축 사료 분석 통합. 평가원 5개년 + 한능검 기출 풀이. 1:1 첨삭 필수."}
    ],
    mistakes: [
      {title: "광종 vs 성종 헷갈림", body: "광종 = 노비안검법·과거제·관복·연호 (왕권 강화). 성종 = 시무 28조·12목·유교 정치 (체제 정비). 광종은 \"왕권\", 성종은 \"체제\"가 키워드예요. \"광-노과관연·성-시12유\"로 외우는 게 답입니다. 1:1 과외에서 비교표가 가장 효율적이에요."},
      {title: "무신 정변 시기·인물 혼동", body: "무신 정변 (1170) = 정중부·이의방·이고가 의종을 폐위. 이후 정중부→경대승→이의민→최충헌 (1196)으로 권력 이동. 최씨 정권 (1196~1258, 4대 60년) = 최충헌·최우·최항·최의. 강화 천도 (1232)는 최우의 결정이에요. 무신 정변 = 1170, 최씨 정권 시작 = 1196 시기 구분이 답."},
      {title: "공민왕의 개혁이 성공했다고 오해", body: "공민왕 개혁은 부분 성공·전체 실패예요. 쌍성총관부 회복·반원 자주는 성공했지만, 신돈 실각·홍건적·왜구 침입·권문세족 반발로 좌절. 결국 이성계의 위화도 회군 (1388) → 조선 건국 (1392)으로 이어집니다. \"공민왕 개혁 = 좌절 → 조선 건국 토대\"가 핵심 흐름이에요."}
    ],
    checklist: ["왕건의 호족 통합 정책 3가지?","광종 vs 성종 정책 차이 (왕권 vs 체제)?","무신 정변 (1170)·최씨 정권·강화 천도 흐름?","공민왕 5대 개혁 외웠나요?","팔만대장경·직지·삼국사기·삼국유사 의의?"],
    checklistTitle: "고려 정복 체크리스트",
    checklistSub: "중·고등 학년별 점검",
    faqs: [
      {q: "고려와 조선의 가장 큰 차이는?", a: "고려는 \"호족·문벌귀족·무신·권문세족·신진사대부\"의 다양한 지배층이 차례로 등장한 시대예요. 조선은 \"양반 사대부\"가 일관되게 지배. 또 고려는 불교 중심·다원적 사회 (호족·여성 지위 ↑·재혼 자유), 조선은 유교 중심·획일적 사회 (양반 중심·여성 지위 ↓). 가족·여성 지위·종교는 시험에서 자주 출제됩니다."},
      {q: "강화 천도는 왜 했나요?", a: "1232년 최우가 몽골 침입에 대비해 강화도로 천도했어요. 강화도는 ① 섬이라 몽골 기마병이 못 들어옴, ② 개경과 가까워 행정 가능, ③ 식량 보급 가능. 27년간 강화에서 항쟁하다 1259년 강화·1270년 개경 환도. 팔만대장경 조판 (1236~1251)도 강화 시기에 이루어졌어요. 시험에서 \"왜 강화도?\"는 단골 출제."},
      {q: "삼별초는 누구이며 왜 항쟁했나요?", a: "삼별초는 최씨 정권의 사병 부대 (좌별초·우별초·신의군)였어요. 1270년 개경 환도에 반대해 배중손이 진도, 김통정이 제주도로 옮겨 1273년까지 항쟁. 의의: ① 자주성·민족 의식 표출, ② 몽골에 끝까지 저항. 한계: 무신 정권의 잔재라는 비판도 있어요. 시험에서 \"삼별초의 의의와 한계\"가 자주 출제됩니다."},
      {q: "직지심체요절은 왜 중요한가요?", a: "\"직지\" (1377)는 세계 최고 (最古) 금속활자 인쇄본이에요 (구텐베르크보다 78년 앞섬). 청주 흥덕사에서 인쇄·현재 프랑스 국립도서관 소장 (1972년 박병선 박사 발견). 의의: ① 한국 인쇄 문화의 우수성, ② 금속활자 기술이 고려 시대 이미 완성. 2001년 유네스코 세계기록유산 등재. 시험에서 거의 매년 출제되는 핵심 문화재예요."}
    ],
    related: [{label: "통일신라·발해", href: "/study/history/period/nambukguk/"},{label: "조선", href: "/study/history/period/joseon/"},{label: "한국사 연표 정리", href: "/study/history/exam/timeline/"},{label: "사료 분석", href: "/study/history/exam/material/"},{label: "한국사 학년별 로드맵", href: "/study/history/"}],
