      body: "조선은 한국사 시험에서 출제 비중 30%로 최대 시대예요. 매년 6~10문항 고정 출제됩니다. 1392년 이성계 건국부터 1897년 대한제국 선포까지 505년 역사인데, \"전기 (15세기 안정) → 임진왜란·병자호란 (16~17세기 전쟁) → 붕당·탕평·세도정치 (17~19세기 정치 변화) → 실학·천주교·서민 문화 (사상·문화)\" 4단계 흐름이 핵심입니다. 세종·임진왜란·영조·정조·실학은 절대 놓치면 안 돼요. 1:1 과외에서 조선은 8~12시간 (가장 긴 시간) 투자가 필요합니다. 하지만 조선만 잘 잡으면 한국사 1·2등급의 절반은 확보돼요."
