      body: "현대사 (1945~현재)는 한국사 시험에서 매년 2~3문항 출제되는 영역이에요 (출제 비중 10~15%). 80년의 짧지만 격동적인 역사로, \"광복·정부 수립 (1945~48) → 6·25전쟁 (1950~53) → 민주화 운동 (1960~87) → 산업화·국제화 (1960~현재)\" 4단계 흐름이 핵심입니다. 4·19혁명 (1960)·5·16군사정변 (1961)·5·18광주민주화운동 (1980)·6월항쟁 (1987)이 시기 매칭에서 단골 출제예요. 또 경제 개발 5개년 계획·새마을운동·IMF·한일월드컵 등 산업화 흐름도 중요. 현대사는 \"우리 부모님·할아버지의 시대\"라 가족 인터뷰로 이해도가 높아져요. 1:1 과외에서 현대사는 4~6시간이면 정복 가능합니다."
